import re,glob,os
tag=re.compile(r'<app-pill(?=[\s/>])((?:"[^"]*"|\'[^\']*\'|[^>"\'])*)>',re.S)
attr=re.compile(r'\s+(\[?)(label|variant|disableTooltip)(\]?)=("([^"]*)"|\'([^\']*)\')')
M={'info':'neutral','success':'positive','warning':'caution'}
def neg(e):
    e=e.strip()
    if e=='true':return 'false'
    if e=='false':return 'true'
    m=re.fullmatch(r'!\((.*)\)',e)
    if m and balanced(m.group(1)):return m.group(1)
    if re.fullmatch(r'![\w.?\[\]\'()]+',e) and not e.startswith('!('):return e[1:]
    if re.fullmatch(r'[\w.?\[\]\'()]+',e):return '!'+e
    return '!(%s)'%e
def balanced(s):
    d=0
    for ch in s:
        d+=ch=='(';d-=ch==')'
        if d<0:return False
    return d==0
def tone_expr(e):
    if '?' in e and re.search(r"'(info|success|warning)'",e):
        return re.sub(r"'(info|success|warning)'",lambda m:"'%s'"%M[m.group(1)],e),False
    return e,True
def conv(s):
    pipe=False
    out=[];pos=0
    for m in tag.finditer(s):
        a=m.group(1);selfc=a.rstrip().endswith('/')
        if selfc:a=a.rstrip()[:-1]
        label=None
        def rep(x):
            nonlocal label,pipe
            br,name,_,_,v1,v2=x.groups();v=v1 if v1 is not None else v2
            q='"' if v1 is not None else "'"
            if name=='label':
                label=('{{ %s }}'%v.strip()) if br else v
                return ''
            if name=='variant':
                if br:
                    e,p=tone_expr(v)
                    if p:pipe=True;return ' [tone]=%s%s | pillTone%s'%(q,e.strip(),q)
                    return ' [tone]=%s%s%s'%(q,e,q)
                return ' tone=%s%s%s'%(q,M[v],q)
            return ' [tooltip]=%s%s%s'%(q,neg(v),q)
        a2=attr.sub(rep,a)
        assert label is not None,m.group(0)
        end=m.end();new='<app-pill'+a2+'>'+label+'</app-pill>'
        if selfc:
            pass
        else:
            c=re.compile(r'\s*</app-pill>').match(s,end)
            assert c,m.group(0)
            end=c.end()
        out.append(s[pos:m.start()]);out.append(new);pos=end
    out.append(s[pos:]);return ''.join(out),pipe
for d in sorted(glob.glob('src/app/features/feature-*')):
    ts=glob.glob(d+'/*.ts')[0];h=glob.glob(d+'/*.html')
    pipe=False
    for f in h+[ts]:
        s=open(f).read()
        if '<app-pill' not in s:continue
        n,p=conv(s);pipe|=p;open(f,'w').write(n)
    if pipe:
        s=open(ts).read()
        s=s.replace('imports: [ PillComponent,','imports: [ PillComponent, PillTonePipe,',1)
        s=s.replace('import { PillComponent, type PillVariant } from "../../lib/pill.component";','import { PillComponent, type PillVariant } from "../../lib/pill.component";\nimport { PillTonePipe } from "../../lib/pill-tone.pipe";',1)
        open(ts,'w').write(s)
E
